            edges.add((u, v))

    # Start with a triangle
    add_edge(0, 1)
    add_edge(1, 2)
    add_edge(2, 0)

    for _ in range(n - 3):
        u = random.choice(nodes)
        v = random.choice(nodes)

        if u == v or (u, v) in edges or (v, u) in edges:
            continue

        # Ensure the graph remains planar
        for w in nodes:
            if (w, u) in edges and (w, v) in edges:
                continue
            add_edge(u, v)
            break

    return list(edges)

def term_overlap_graph(graph):
